CREATE TABLE "categorias_imputacion" (
	"id"	INTEGER,
	"nombre"	TEXT NOT NULL UNIQUE,
	"tipo"	TEXT NOT NULL, -- Ej: 'Gasto Fijo', 'Pago a Terceros', 'Provisión'
	PRIMARY KEY("id" AUTOINCREMENT)
);
