CREATE TABLE compras_materia_prima (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    proveedor_id INTEGER NOT NULL REFERENCES proveedores(id),
    materia_prima_id INTEGER NOT NULL REFERENCES materias_primas(id),
    fecha TEXT NOT NULL,
    cantidad REAL NOT NULL,
    precio_unitario REAL NOT NULL,  -- precio por unidad (kg/litro)
    costo_total REAL NOT NULL,      -- precio_unitario * cantidad + flete + otros
    costo_flete REAL DEFAULT 0,
    otros_costos REAL DEFAULT 0,
    moneda TEXT DEFAULT 'ARS',
    cotizacion_usd REAL DEFAULT NULL,
    observaciones TEXT, numero_comprobante TEXT,
    FOREIGN KEY(proveedor_id) REFERENCES proveedores(id),
    FOREIGN KEY(materia_prima_id) REFERENCES materias_primas(id)
);
