    "id" INTEGER PRIMARY KEY AUTOINCREMENT,
    "nombre" TEXT NOT NULL,
    "sueldo_base" REAL NOT NULL,
    "horas_jornada_diaria" REAL NOT NULL,
    "horario_entrada" TEXT NOT NULL,
