CREATE TABLE "entradas_envases" (
	"id"	INTEGER,
	"proveedor_id"	INTEGER NOT NULL,
	"fecha_ingreso"	TEXT NOT NULL,
	"numero_comprobante"	TEXT NOT NULL,
	"envase_id"	INTEGER NOT NULL,
	"cantidad_ingresada"	INTEGER NOT NULL,
	"precio_unitario"	REAL,
	"cliente_asignado_id"	INTEGER, -- Cliente al que se asigna el stock
	"producto_asignado_id" INTEGER, lote TEXT, -- Producto al que se asigna el envase (opcional, si es por producto)
	PRIMARY KEY("id" AUTOINCREMENT),
	FOREIGN KEY("proveedor_id") REFERENCES "proveedores"("id"),
	FOREIGN KEY("envase_id") REFERENCES "envases"("id"),
	FOREIGN KEY("cliente_asignado_id") REFERENCES "clientes"("id"),
	FOREIGN KEY("producto_asignado_id") REFERENCES "recetas"("id") -- Asumiendo que "productos" es "recetas"
);
