CREATE TABLE "gastos" (
    "id" INTEGER PRIMARY KEY AUTOINCREMENT,
    "fecha_factura" TEXT NOT NULL,         -- Fecha de emisión del gasto (periodo)
    "fecha_pago" TEXT,                    -- Fecha en que se pagó (puede ser NULL si está pendiente)
    "beneficiario_nombre" TEXT NOT NULL,  -- **NUEVO CAMPO:** Quién recibe el pago (Ej: 'EDET S.A.', 'SAT', 'Inmobiliaria X')
    "categoria_id" INTEGER NOT NULL,      -- FK a 'categorias_imputacion' (Clasificación del gasto: 'Servicio Eléctrico', 'Alquileres')
    "numero_comprobante" TEXT UNIQUE,     -- Número de la factura de EDET, ticket, recibo.
    "importe_total" REAL NOT NULL,        -- Monto total del gasto.
    "moneda" TEXT DEFAULT 'ARS',
    "observaciones" TEXT,
    FOREIGN KEY("categoria_id") REFERENCES "categorias_imputacion"("id")
);
