CREATE TABLE movimientos_envases (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    envase_id INTEGER NOT NULL,
    fecha TEXT NOT NULL,
    cantidad REAL NOT NULL,
    tipo_movimiento TEXT CHECK(tipo_movimiento IN ('Ingreso', 'Egreso')) NOT NULL,
    observacion TEXT, lote TEXT,
    FOREIGN KEY(envase_id) REFERENCES envases(id)
);
