CREATE TABLE movimientos_materia_prima (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    materia_prima_id INTEGER NOT NULL,
    lote TEXT NOT NULL,
    fecha TEXT NOT NULL,
    cantidad REAL NOT NULL,
    tipo_movimiento TEXT NOT NULL CHECK(tipo_movimiento IN ('ingreso', 'egreso')),
    destino TEXT NOT NULL CHECK(destino IN ('produccion', 'laboratorio', 'otro')),
    costo_flete REAL DEFAULT 0,
    otros_costos REAL DEFAULT 0, precio_unitario REAL DEFAULT 0, compra_id INTEGER REFERENCES compras_materia_prima(id), precio_unitario_total REAL DEFAULT 0, reactor INTEGER, observaciones TEXT,
    FOREIGN KEY(materia_prima_id) REFERENCES materias_primas(id)
);
